import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"温公易说 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"温公易说 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/wengong/034.md","filePath":"zh/classics/wengong/034.md"}'),n={name:"zh/classics/wengong/034.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><h3 id="彖曰-遁亨-遁而亨也。刚当位而应-与时行也。小利贞-浸而长也。遁之时义大矣哉。" tabindex="-1">彖曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉。 <a class="header-anchor" href="#彖曰-遁亨-遁而亨也。刚当位而应-与时行也。小利贞-浸而长也。遁之时义大矣哉。" aria-label="Permalink to “彖曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉。”">​</a></h3><h3 id="象曰-天下有山-遁。君子以远小人-不恶而严。" tabindex="-1">象曰：天下有山，遁。君子以远小人，不恶而严。 <a class="header-anchor" href="#象曰-天下有山-遁。君子以远小人-不恶而严。" aria-label="Permalink to “象曰：天下有山，遁。君子以远小人，不恶而严。”">​</a></h3><h3 id="初六-遁尾-厉-勿用有攸往-象曰-遁尾之厉-不往何灾也。" tabindex="-1">初六：遁尾，厉，勿用有攸往 象曰：遁尾之厉，不往何灾也。 <a class="header-anchor" href="#初六-遁尾-厉-勿用有攸往-象曰-遁尾之厉-不往何灾也。" aria-label="Permalink to “初六：遁尾，厉，勿用有攸往 象曰：遁尾之厉，不往何灾也。”">​</a></h3><h3 id="六二-执之用黄牛之革-莫之胜说-象曰-执用黄牛-固志也。" tabindex="-1">六二：执之用黄牛之革，莫之胜说 象曰：执用黄牛，固志也。 <a class="header-anchor" href="#六二-执之用黄牛之革-莫之胜说-象曰-执用黄牛-固志也。" aria-label="Permalink to “六二：执之用黄牛之革，莫之胜说 象曰：执用黄牛，固志也。”">​</a></h3><p>遁之为道，避内而趋外者也。二以柔居内，未得自去者也。然履中守正，和而不流，执志之坚，人不能夺，故曰执之用黄牛之革，莫之胜说。黄者中也，牛革取其柔而坚韧也。</p><h3 id="九三-系遁-有疾-厉-畜臣妾吉-象曰-系遁之厉-有疾惫也。畜臣妾吉-不可大事也。" tabindex="-1">九三：系遁，有疾，厉，畜臣妾吉 象曰：系遁之厉，有疾惫也。畜臣妾吉，不可大事也。 <a class="header-anchor" href="#九三-系遁-有疾-厉-畜臣妾吉-象曰-系遁之厉-有疾惫也。畜臣妾吉-不可大事也。" aria-label="Permalink to “九三：系遁，有疾，厉，畜臣妾吉 象曰：系遁之厉，有疾惫也。畜臣妾吉，不可大事也。”">​</a></h3><p>三以刚德居位，而宴安于内，系于荣利，不能自退，故曰有疾。小人道长，贪位不退，危之道也，故曰厉。臣妾者，系于人而不能自去者也，故畜臣妾吉。</p><h3 id="九四-好遁-君子吉-小人否-象曰-君子好遁-小人否也。" tabindex="-1">九四：好遁，君子吉，小人否 象曰：君子好遁，小人否也。 <a class="header-anchor" href="#九四-好遁-君子吉-小人否-象曰-君子好遁-小人否也。" aria-label="Permalink to “九四：好遁，君子吉，小人否 象曰：君子好遁，小人否也。”">​</a></h3><p>四以刚德而处非其位，君子难进而易退，小人反是者也，故曰好遁君子吉，小人否也。</p><h3 id="九五-嘉遁-贞吉-象曰-嘉遁贞吉-以正志也。" tabindex="-1">九五：嘉遁，贞吉 象曰：嘉遁贞吉，以正志也。 <a class="header-anchor" href="#九五-嘉遁-贞吉-象曰-嘉遁贞吉-以正志也。" aria-label="Permalink to “九五：嘉遁，贞吉 象曰：嘉遁贞吉，以正志也。”">​</a></h3><p>中正德之嘉也。君子邦有道则见，邦无道则隐，可以进而进，可以退而退，不失其时，以中正为心者也，故曰嘉遁贞吉。</p><h3 id="上九-肥遁-无不利-象曰-肥遁无不利-无所疑也。" tabindex="-1">上九：肥遁，无不利 象曰：肥遁无不利，无所疑也。 <a class="header-anchor" href="#上九-肥遁-无不利-象曰-肥遁无不利-无所疑也。" aria-label="Permalink to “上九：肥遁，无不利 象曰：肥遁无不利，无所疑也。”">​</a></h3>',13)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
